sharedContracts.interfaceSketch:
export interface ConfigSyncEngine {
  /** Pull daemon values into the native settings mirror (activation + manual refresh). */
  pullFromDaemon(): Promise<void>;
  /** React to a native settings change: diff vs snapshot, validate, write, revert-on-reject. */
  applyChanges(changed: readonly ChangedKey[]): Promise<void>;
}
export interface ChangedKey { readonly key: string; readonly value: unknown; }
export interface SettingsStore {
  read(key: string): unknown;
  write(key: string, value: unknown): Promise<void>;
  snapshot(): ReadonlyMap<string, unknown>;
}
export interface Notifier { error(message: string): void; }
export interface ConfigGateway {
  catalog(): Promise<ConfigCatalogSnapshot>;
  writeKey(key: string, value: unknown): Promise<ConfigWriteResult>;
}
export type ConfigWriteResult = { ok: true } | { ok: false; reason: string };
export interface ConfigCatalogSnapshot { readonly values: ReadonlyMap<string, unknown>; readonly repos: readonly RepoRef[]; }
export interface RepoRef { readonly path: string; readonly name: string; }

export type DetailTab = 'daemon' | 'workflows' | 'debug';
export interface WebviewPanelHost {
  openDetailedStatus(tab?: DetailTab): void;
  openRepoConfiguration(): void;
}
export interface DaemonDataGateway {
  status(): Promise<DaemonStatusView>;
  workflowChain(): Promise<WorkflowChainView>;
  mcpClients(): Promise<readonly McpClientView[]>;
  registeredRepos(): Promise<readonly RepoRef[]>;
  scanOrphans(): Promise<readonly OrphanProcess[]>;
}
export interface DaemonStatusView { readonly state: string; readonly detail?: string; }
export interface WorkflowChainView { readonly rows: readonly WorkflowChainRow[]; }
export interface WorkflowChainRow { readonly slug: string; readonly stage: string; readonly status: string; }
export interface McpClientView { readonly host: string; readonly wired: boolean; }
export interface OrphanProcess { readonly pid: number; readonly command: string; }
export interface RepoRef { readonly path: string; readonly name: string; }
